class Solution {
public:
    int countBeautifulPairs(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            string s = to_string(nums[i]);
            int first_digit = s[0] - '0';
            for (int j = i + 1; j < n; ++j) {
                int last_digit = nums[j] % 10;
                if (std::gcd(first_digit, last_digit) == 1) {
                    ans++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public int countBeautifulPairs(int[] nums) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int first = Integer.parseInt(Integer.toString(nums[i]).substring(0, 1));
            for (int j = i + 1; j < n; j++) {
                int last = nums[j] % 10;
                if (gcd(first, last) == 1) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

var countBeautifulPairs = function(nums) {
    function gcd(a, b) {
        return b === 0 ? a : gcd(b, a % b);
    }
    const n = nums.length;
    let ans = 0;
